#!/usr/bin/env bash
# Compiles text/ with skalder and vendors the skald-lua runtime into the mod.
# PZ's require discards return values, so every generated file registers itself as a global instead.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")" && pwd)"
SKALD_LUA="${SKALD_LUA:-$HOME/repos/skald-lua}"
OUT="$ROOT/CDCLastHope/42/media/lua/client/CDCLastHope/skald"
REQ="CDCLastHope/skald"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

skalder --compile lua "$ROOT/text" -o "$TMP/story"

rm -rf "$OUT"
mkdir -p "$OUT/story"

sed 's|^return Skald$|SkaldRuntime = Skald|' "$SKALD_LUA/src/skald.lua" > "$OUT/SkaldRuntime.lua"
grep -q '^SkaldRuntime = Skald$' "$OUT/SkaldRuntime.lua" || { echo "runtime rewrite failed" >&2; exit 1; }

sed 's|^return {$|CDCSkaldCodex = {|' "$TMP/story/_codex.lua" > "$OUT/story/codex.lua"
grep -q '^CDCSkaldCodex = {$' "$OUT/story/codex.lua" || { echo "codex rewrite failed" >&2; exit 1; }

requires=("$REQ/SkaldRuntime" "$REQ/story/codex")
while IFS= read -r f; do
    rel="${f#"$TMP/story/"}"
    key="${rel%.lua}.ska"
    mkdir -p "$OUT/story/$(dirname "$rel")"
    {
        echo 'CDCSkaldModules = CDCSkaldModules or {}'
        sed "s|^return {\$|CDCSkaldModules[\"$key\"] = {|" "$f"
    } > "$OUT/story/$rel"
    grep -q "^CDCSkaldModules\[\"$key\"\] = {\$" "$OUT/story/$rel" || { echo "module rewrite failed: $rel" >&2; exit 1; }
    requires+=("$REQ/story/${rel%.lua}")
done < <(find "$TMP/story" -name '*.lua' ! -name '_codex.lua' | sort)

{
    echo '-- generated by compile.sh. do not edit.'
    for r in "${requires[@]}"; do echo "require \"$r\""; done
} > "$OUT/index.lua"

echo "compiled $(( ${#requires[@]} - 2 )) modules -> $OUT"
